'use client';

import { useContext } from 'react';
import { AppContext, AppContextType } from '@/contexts/app-context';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { LogOut, User, Settings, HelpCircle, FileText, BarChart, DollarSign, PlusCircle } from 'lucide-react';
import { useRouter } from 'next/navigation';

export default function HomePage() {
  const { t, user, logout } = useContext(AppContext) as AppContextType;
  const router = useRouter();

  const mainCards = [
    { title: t('new-service'), icon: <PlusCircle className="w-12 h-12" />, path: '/' },
    { title: t('expense-management-title'), icon: <DollarSign className="w-12 h-12" />, path: '/inventory-expenses' },
    { title: t('reports-tab-text'), icon: <BarChart className="w-12 h-12" />, path: '/reports' },
    { title: t('documents-title'), icon: <FileText className="w-12 h-12" />, path: '/documents' }, // Assuming a documents path
  ];

  const smallCards = [
    { title: t('customer-history-tab-text'), icon: <User className="w-6 h-6" />, path: '/customer-history' },
    { title: t('settings-title'), icon: <Settings className="w-6 h-6" />, path: '/settings' },
    { title: t('support-tab-text'), icon: <HelpCircle className="w-6 h-6" />, path: '/support' },
  ];

  return (
    <div className="flex flex-col h-screen bg-gray-900 text-white p-4">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-lg font-semibold">{user?.email}</h2>
        <Button variant="ghost" size="icon" onClick={logout}>
          <LogOut className="w-6 h-6" />
        </Button>
      </div>

      <div className="text-center mb-8">
        <h1 className="text-2xl font-bold">{t('app-title')}</h1>
      </div>

      <div className="grid grid-cols-2 gap-4 flex-grow">
        {mainCards.map((card) => (
          <Card
            key={card.title}
            className="bg-gray-800 border-gray-700 flex flex-col items-center justify-center text-center cursor-pointer"
            onClick={() => router.push(card.path)}
          >
            <CardHeader>
              {card.icon}
            </CardHeader>
            <CardContent>
              <CardTitle>{card.title}</CardTitle>
            </CardContent>
          </Card>
        ))}
      </div>

      <div className="grid grid-cols-3 gap-4 mt-4">
        {smallCards.map((card) => (
          <Card
            key={card.title}
            className="bg-gray-800 border-gray-700 flex flex-col items-center justify-center text-center cursor-pointer p-4"
            onClick={() => router.push(card.path)}
          >
            {card.icon}
            <span className="text-sm mt-2">{card.title}</span>
          </Card>
        ))}
      </div>
    </div>
  );
}
